 for begin in [0,12800,25600]:
  records=[struct.pack('<10i',i,*([0]*7),expected[i] if i in expected else -77,1 if i in expected else -77) for i in range(begin,begin+12800)];cases=p/f'road-{command}-index-cases-{begin}.bin';cases.write_bytes(struct.pack('<I',12800)+b''.join(records));run=subprocess.run([str((p/'road-source-index-probe.exe').resolve()),str(sf),str(cases),str(p/'road-correction-reciprocal.bin'),str(p/f'road-{command}-span-gpu-ring.bin'),str(texture)],capture_output=True,text=True,timeout=90);assert run.returncode==0,run.stdout+run.stderr;checks.append(dict(command=command,begin=begin,cases=12800,output=run.stdout))
